CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,telegram_id BIGINT UNIQUE NOT NULL,points BIGINT NOT NULL DEFAULT 0,balance_usd NUMERIC(18,6) NOT NULL DEFAULT 0,risk_score INT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS game_sessions(id UUID PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),started_at TIMESTAMPTZ NOT NULL,finished_at TIMESTAMPTZ,status TEXT NOT NULL DEFAULT 'active',score BIGINT NOT NULL DEFAULT 0,risk_score INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS withdrawals(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),requested_amount NUMERIC(18,6) NOT NULL,fee NUMERIC(18,6) NOT NULL,net_amount NUMERIC(18,6) NOT NULL,status TEXT NOT NULL DEFAULT 'pending_locked',transaction_id TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),processed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS payout_fund(id SMALLINT PRIMARY KEY DEFAULT 1,balance NUMERIC(18,6) NOT NULL DEFAULT 0,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS fund_transactions(id BIGSERIAL PRIMARY KEY,amount NUMERIC(18,6) NOT NULL,kind TEXT NOT NULL,reference TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
